from collections import defaultdict

def colorcomps(grid, bg=8, borders=(1,1)):
 R,C=len(grid),len(grid[0]); seen=set(); out=[]
 for r in range(1,R-1):
  for c in range(1,C-1):
   col=grid[r][c]
   if col==bg or (r,c) in seen: continue
   st=[(r,c)]; seen.add((r,c)); cells=[]
   while st:
    x,y=st.pop(); cells.append((x,y))
    for z in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
     if 1<=z[0]<R-1 and 1<=z[1]<C-1 and grid[z[0]][z[1]]==col and z not in seen:
      seen.add(z);st.append(z)
   out.append((col,cells))
 return sorted(out,key=lambda x:min(x[1]))
